def check_cookie(cookie_session_id=None, label=None, force_refresh=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0444000" if __import__("os").path.isdir("./environment_mix/0444000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_log():
        # Best-effort: only create if missing; schema not provided, but observable dynamics required.
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])

    def _log(endpoint, cred_id, status, latency_ms, error=None, meta=None):
        _ensure_log()
        logs = _load("request_logs.json")
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "cookie_session_id": cred_id,
            "status": status,
            "latency_ms": int(latency_ms),
            "error": error,
            "meta": meta or {},
            "created_at": _now(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = time.time()
    endpoint = "check_cookie"
    used_cookie_id = None
    try:
        if cookie_session_id is not None:
            if not isinstance(cookie_session_id, str):
                _log(endpoint, None, "error", (time.time() - t0) * 1000, error="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "cookie_session_id must be a string")
            if not re.match(r"^xhs_sess_[A-Za-z0-9]+$", cookie_session_id):
                _log(endpoint, None, "error", (time.time() - t0) * 1000, error="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "cookie_session_id format invalid", field="cookie_session_id")
        if label is not None and not isinstance(label, str):
            _log(endpoint, None, "error", (time.time() - t0) * 1000, error="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "label must be a string")
        if force_refresh is not None and not isinstance(force_refresh, bool):
            _log(endpoint, None, "error", (time.time() - t0) * 1000, error="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "force_refresh must be a boolean")

        sessions = _load("cookie_sessions.json")
        if cookie_session_id:
            sess = next((s for s in sessions if s.get("id") == cookie_session_id), None)
            if not sess:
                _log(endpoint, cookie_session_id, "error", (time.time() - t0) * 1000, error="NOT_FOUND")
                return _err("NOT_FOUND", "cookie session not found", cookie_session_id=cookie_session_id)
            candidates = [sess]
        else:
            candidates = [s for s in sessions if s.get("status") in ("active", "limited")]
            if label is not None:
                candidates = [s for s in candidates if s.get("label") == label]
            # pick lowest risk_score then most recently checked ok
            def _key(s):
                rs = s.get("risk_score", 1.0)
                lca = _parse_dt(s.get("last_checked_at")) or datetime.datetime(1970, 1, 1)
                return (float(rs) if isinstance(rs, (int, float)) else 1.0, -lca.timestamp())
            candidates.sort(key=_key)

            if not candidates:
                _log(endpoint, None, "error", (time.time() - t0) * 1000, error="UNAUTHORIZED")
                return _err("UNAUTHORIZED", "no usable cookie sessions available")

        sess = candidates[0]
        used_cookie_id = sess.get("id")

        # must probe only if status in active/limited per business rule (for explicit id too)
        if sess.get("status") not in ("active", "limited"):
            _log(endpoint, used_cookie_id, "error", (time.time() - t0) * 1000, error="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "cookie session not in a probeable state", status=sess.get("status"))

        # Cache reuse (avoid frequent checks) unless force_refresh
        ttl_seconds = 120
        last_checked = _parse_dt(sess.get("last_checked_at"))
        if (force_refresh is not True) and last_checked and (datetime.datetime.utcnow() - last_checked).total_seconds() <= ttl_seconds:
            # return current status info
            _log(endpoint, used_cookie_id, "ok", (time.time() - t0) * 1000)
            return {
                "cookie_session": sess,
                "selected": True if (cookie_session_id is None) else False,
                "reused_last_check": True,
            }

        # "Probe" simulation based on stored state/risk (offline). Real service would call upstream.
        rs = sess.get("risk_score", 0.0)
        if not isinstance(rs, (int, float)):
            rs = 0.0
        ok = True
        new_status = sess.get("status")
        err_msg = None

        if sess.get("status") in ("expired", "banned", "disabled"):
            ok = False
            err_msg = f"session status={sess.get('status')}"
            new_status = sess.get("status")
        else:
            # Risk-driven throttling outcomes
            if rs >= 0.95:
                ok = False
                err_msg = "risk_control: banned"
                new_status = "banned"
            elif rs > 0.7:
                # likely limited, still "ok" but restricted
                ok = True
                new_status = "limited"
            else:
                ok = True
                new_status = "active"

        # Enforce lifecycle transitions
        transitions = {
            "active": {"limited", "expired", "banned", "disabled"},
            "limited": {"active", "expired", "banned", "disabled"},
            "expired": {"active", "disabled"},
            "banned": {"disabled"},
            "disabled": {"active"},
        }
        cur = sess.get("status")
        if new_status != cur:
            if new_status not in transitions.get(cur, set()):
                _log(endpoint, used_cookie_id, "error", (time.time() - t0) * 1000, error="INVALID_TRANSITION")
                return _err("INVALID_TRANSITION", "illegal status transition", from_status=cur, to_status=new_status)

        sess["last_checked_at"] = _now()
        sess["updated_at"] = _now()
        if ok:
            sess["last_check_ok"] = True
            sess["last_check_error"] = None
            sess["status"] = new_status
            # constraints: last_check_ok implies status in active/limited
            if sess["status"] not in ("active", "limited"):
                sess["status"] = "limited"
        else:
            sess["last_check_ok"] = False
            sess["last_check_error"] = err_msg or "check failed"
            # constraints: expired/banned implies last_check_ok=false satisfied
            sess["status"] = new_status if new_status in ("expired", "banned", "limited") else "expired"
            if sess["status"] == "disabled" and not sess.get("disabled_reason"):
                sess["disabled_reason"] = "auto-disabled after failed check"

        # enforce risk_score range
        if sess.get("risk_score") is None:
            sess["risk_score"] = 0.0
        if not isinstance(sess["risk_score"], (int, float)) or sess["risk_score"] < 0 or sess["risk_score"] > 1:
            _log(endpoint, used_cookie_id, "error", (time.time() - t0) * 1000, error="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "risk_score out of range in stored session", cookie_session_id=used_cookie_id)

        # persist
        for i, s in enumerate(sessions):
            if s.get("id") == used_cookie_id:
                sessions[i] = sess
                break
        _save("cookie_sessions.json", sessions)

        if not ok:
            _log(endpoint, used_cookie_id, "error", (time.time() - t0) * 1000, error="UNAUTHORIZED", meta={"status": sess.get("status")})
            return _err("UNAUTHORIZED", "cookie session check failed", cookie_session_id=used_cookie_id, status=sess.get("status"), last_check_error=sess.get("last_check_error"))

        _log(endpoint, used_cookie_id, "ok", (time.time() - t0) * 1000, meta={"status": sess.get("status")})
        return {
            "cookie_session": sess,
            "selected": True if (cookie_session_id is None) else False,
            "reused_last_check": False,
        }
    except Exception as e:
        _log(endpoint, used_cookie_id, "error", (time.time() - t0) * 1000, error="INTERNAL_ERROR")
        return _err("CONFLICT", "internal error", detail=str(e))

def search_notes(keywords, cookie_session_id=None, limit=None, cursor=None, sort=None, refresh=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0444000" if __import__("os").path.isdir("./environment_mix/0444000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_log():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])

    def _log(endpoint, cred_id, status, latency_ms, error=None, meta=None):
        _ensure_log()
        logs = _load("request_logs.json")
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "cookie_session_id": cred_id,
            "status": status,
            "latency_ms": int(latency_ms),
            "error": error,
            "meta": meta or {},
            "created_at": _now(),
        })
        _save("request_logs.json", logs)

    def _gen_id(prefix, rows):
        return f"{prefix}_{int(time.time()*1000)}_{os.getpid()}_{len(rows)+1}"

    def _select_session(sessions, requested_id=None):
        if requested_id:
            s = next((x for x in sessions if x.get("id") == requested_id), None)
            if not s:
                return "NOT_FOUND", None
            if s.get("status") not in ("active", "limited"):
                return "UNAUTHORIZED", None
            return None, s
        candidates = [s for s in sessions if s.get("status") in ("active", "limited")]
        candidates.sort(key=lambda x: (float(x.get("risk_score", 1.0)) if isinstance(x.get("risk_score", 1.0), (int, float)) else 1.0))
        return (None, candidates[0]) if candidates else ("UNAUTHORIZED", None)

    def _rate_limit_check(cookie_id, session_row):
        if not cookie_id or not session_row:
            return None
        limited = session_row.get("status") == "limited"
        rs = session_row.get("risk_score", 0.0)
        high_risk = isinstance(rs, (int, float)) and rs > 0.7
        if not (limited or high_risk):
            return None
        _ensure_log()
        logs = _load("request_logs.json")
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if r.get("cookie_session_id") != cookie_id:
                continue
            if r.get("endpoint") not in ("home_feed", "search_notes", "get_note_content"):
                continue
            ts = _parse_dt(r.get("created_at"))
            if ts and ts >= cutoff:
                cnt += 1
        if cnt >= 30:
            return _err("RATE_LIMIT", "rate limit exceeded for this cookie session", cookie_session_id=cookie_id, limit_per_minute=30)
        return None

    t0 = time.time()
    endpoint = "search_notes"
    used_cookie_id = None
    try:
        if keywords is None or not isinstance(keywords, str) or len(keywords.strip()) == 0:
            _log(endpoint, None, "error", (time.time() - t0) * 1000, error="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "keywords must be a non-empty string", field="keywords")

        if cookie_session_id is not None:
            if not isinstance(cookie_session_id, str):
                _log(endpoint, None, "error", (time.time() - t0) * 1000, error="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "cookie_session_id must be a string")
            if not re.match(r"^xhs_sess_[A-Za-z0-9]+$", cookie_session_id):
                _log(endpoint, None, "error", (time.time() - t0) * 1000, error="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "cookie_session_id format invalid", field="cookie_session_id")
        if limit is not None:
            if not isinstance(limit, int):
                _log(endpoint, None, "error", (time.time() - t0) * 1000, error="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "limit must be an integer")
            if limit < 1 or limit > 50:
                _log(endpoint, None, "error", (time.time() - t0) * 1000, error="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "limit out of range (1-50)", field="limit")
        if cursor is not None and not isinstance(cursor, str):
            _log(endpoint, None, "error", (time.time() - t0) * 1000, error="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a string")
        if sort is not None:
            if not isinstance(sort, str):
                _log(endpoint, None, "error", (time.time() - t0) * 1000, error="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "sort must be a string")
            if sort not in ("relevance", "latest", "hot"):
                _log(endpoint, None, "error", (time.time() - t0) * 1000, error="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "sort must be one of relevance/latest/hot", field="sort")
        if refresh is not None and not isinstance(refresh, bool):
            _log(endpoint, None, "error", (time.time() - t0) * 1000, error="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "refresh must be a boolean")

        limit = 20 if limit is None else limit
        cursor = "" if cursor is None else cursor
        sort = "relevance" if sort is None else sort
        refresh = False if refresh is None else refresh

        sessions = _load("cookie_sessions.json")
        code, sess = _select_session(sessions, cookie_session_id)
        if code == "NOT_FOUND":
            _log(endpoint, cookie_session_id, "error", (time.time() - t0) * 1000, error="NOT_FOUND")
            return _err("NOT_FOUND", "cookie session not found", cookie_session_id=cookie_session_id)
        if code == "UNAUTHORIZED":
            _log(endpoint, cookie_session_id, "error", (time.time() - t0) * 1000, error="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "no usable cookie sessions available")
        used_cookie_id = sess.get("id")

        queries = _load("search_queries.json")

        # request_fingerprint=hash(type+keywords) per business rule (include sort+cursor+limit for page caching)
        fp_src = f"search_notes|{keywords.strip()}|sort={sort}|cursor={cursor}|limit={limit}"
        request_fingerprint = hashlib.sha256(fp_src.encode("utf-8")).hexdigest()

        # Reuse succeeded cached within TTL
        ttl_seconds = 180
        if not refresh:
            existing = next((q for q in queries if q.get("type") == "search_notes" and q.get("request_fingerprint") == request_fingerprint and q.get("status") == "succeeded"), None)
            if existing:
                finished = _parse_dt(existing.get("finished_at"))
                if finished and (datetime.datetime.utcnow() - finished).total_seconds() <= ttl_seconds:
                    qnr = _load("query_note_results.json")
                    notes = _load("notes.json")
                    rows = [r for r in qnr if r.get("search_query_id") == existing.get("id")]
                    rows.sort(key=lambda r: r.get("rank", 10**9))
                    out_notes = []
                    for r in rows[:limit]:
                        n = next((n for n in notes if n.get("id") == r.get("note_id")), None)
                        if n:
                            out_notes.append({"note": n, "rank": r.get("rank"), "snippet": r.get("snippet"), "cover_url": r.get("cover_url"), "extra": r.get("extra")})
                    _log(endpoint, used_cookie_id, "ok", (time.time() - t0) * 1000, meta={"reused_cache": True, "search_query_id": existing.get("id")})
                    return {
                        "search_query": existing,
                        "items": out_notes,
                        "result_count": existing.get("result_count"),
                        "cursor": cursor,
                        "next_cursor": (existing.get("raw_response") or {}).get("next_cursor"),
                        "has_more": bool((existing.get("raw_response") or {}).get("has_more")),
                        "reused_cache": True,
                    }

        rl = _rate_limit_check(used_cookie_id, sess)
        if rl:
            qid = _gen_id("qry", queries)
            now = _now()
            qrow = {
                "id": qid,
                "type": "search_notes",
                "keywords": keywords.strip(),
                "request_fingerprint": request_fingerprint,
                "cookie_session_id": used_cookie_id,
                "status": "failed",
                "http_status": None,
                "error_code": "RATE_LIMIT",
                "error_message": rl["error"]["message"],
                "result_count": None,
                "raw_response": None,
                "started_at": now,
                "finished_at": now,
                "created_at": now,
                "updated_at": now,
            }
            queries.append(qrow)
            _save("search_queries.json", queries)
            _log(endpoint, used_cookie_id, "error", (time.time() - t0) * 1000, error="RATE_LIMIT")
            return rl

        # create queued->running->succeeded/failed
        qid = _gen_id("qry", queries)
        now = _now()
        qrow = {
            "id": qid,
            "type": "search_notes",
            "keywords": keywords.strip(),
            "request_fingerprint": request_fingerprint,
            "cookie_session_id": used_cookie_id,
            "status": "queued",
            "http_status": None,
            "error_code": None,
            "error_message": None,
            "result_count": None,
            "raw_response": None,
            "started_at": None,
            "finished_at": None,
            "created_at": now,
            "updated_at": now,
        }
        queries.append(qrow)
        qrow["status"] = "running"
        qrow["started_at"] = _now()
        qrow["updated_at"] = qrow["started_at"]

        # Offline upstream simulation
        base = hashlib.sha256(f"{keywords.strip()}|{sort}|{cursor}".encode("utf-8")).hexdigest()
        seed = int(base[:8], 16)
        items = []
        for i in range(limit):
            platform_note_id = f"s_{(seed + i) % 100000000}"
            token = hashlib.sha256(f"{platform_note_id}|{request_fingerprint}".encode("utf-8")).hexdigest()[:16]
            tokenized_url = f"https://www.xiaohongshu.com/explore/{platform_note_id}?xsec_token={token}"
            items.append({
                "platform_note_id": platform_note_id,
                "tokenized_url": tokenized_url,
                "xsec_token": token,
                "title": f"{keywords.strip()} - {sort} - {platform_note_id}",
                "author_platform_id": f"u_{(seed // 11 + i) % 1000000}",
                "author_name": f"User{(seed // 11 + i) % 1000000}",
                "snippet": f"Search({sort}) hit for '{keywords.strip()}': {platform_note_id}",
                "cover_url": f"https://cdn.example.com/{platform_note_id}.jpg",
                "extra": {"sort": sort, "cursor": cursor, "idx": i},
            })
        raw_response = {
            "items": items,
            "has_more": True,
            "next_cursor": hashlib.sha1(f"{request_fingerprint}|{cursor}|next".encode("utf-8")).hexdigest()[:12],
            "sort": sort,
            "keywords": keywords.strip(),
        }

        notes = _load("notes.json")
        results = _load("query_note_results.json")

        def _find_note(it):
            pid = it.get("platform_note_id")
            turl = it.get("tokenized_url")
            for n in notes:
                if pid and n.get("platform_note_id") == pid:
                    return n
                if turl and n.get("tokenized_url") == turl:
                    return n
            return None

        now2 = _now()
        created_results = 0
        for idx, it in enumerate(items, start=1):
            n = _find_note(it)
            if n is None:
                nid = _gen_id("note", notes)
                n = {
                    "id": nid,
                    "platform_note_id": it.get("platform_note_id"),
                    "canonical_url": None,
                    "tokenized_url": it.get("tokenized_url"),
                    "xsec_token": it.get("xsec_token"),
                    "title": it.get("title"),
                    "author_platform_id": it.get("author_platform_id"),
                    "author_name": it.get("author_name"),
                    "content_text": None,
                    "content_raw": None,
                    "last_content_fetched_at": None,
                    "last_comments_fetched_at": None,
                    "visibility": "unknown",
                    "status": "discovered",
                    "created_at": now2,
                    "updated_at": now2,
                }
                if n.get("tokenized_url") and not n.get("xsec_token"):
                    qrow["status"] = "failed"
                    qrow["error_code"] = "VALIDATION_ERROR"
                    qrow["error_message"] = "tokenized_url missing xsec_token"
                    qrow["finished_at"] = _now()
                    qrow["updated_at"] = qrow["finished_at"]
                    _save("search_queries.json", queries)
                    _log(endpoint, used_cookie_id, "error", (time.time() - t0) * 1000, error="VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "invalid upstream item missing xsec_token")
                notes.append(n)
            else:
                n["tokenized_url"] = it.get("tokenized_url") or n.get("tokenized_url")
                n["xsec_token"] = it.get("xsec_token") or n.get("xsec_token")
                n["title"] = it.get("title") or n.get("title")
                n["author_platform_id"] = it.get("author_platform_id") or n.get("author_platform_id")
                n["author_name"] = it.get("author_name") or n.get("author_name")
                n["updated_at"] = now2

            if any(r for r in results if r.get("search_query_id") == qid and r.get("rank") == idx):
                continue
            if any(r for r in results if r.get("search_query_id") == qid and r.get("note_id") == n.get("id")):
                continue
            rid = _gen_id("qnr", results)
            results.append({
                "id": rid,
                "search_query_id": qid,
                "note_id": n.get("id"),
                "rank": idx,
                "snippet": it.get("snippet"),
                "cover_url": it.get("cover_url"),
                "extra": it.get("extra"),
                "created_at": now2,
                "updated_at": now2,
            })
            created_results += 1

        if created_results == 0:
            qrow["status"] = "failed"
            qrow["error_code"] = "CONFLICT"
            qrow["error_message"] = "no results written"
            qrow["finished_at"] = _now()
            qrow["updated_at"] = qrow["finished_at"]
            _save("search_queries.json", queries)
            _log(endpoint, used_cookie_id, "error", (time.time() - t0) * 1000, error="CONFLICT")
            return _err("CONFLICT", "no success without effect: no results written")

        qrow["status"] = "succeeded"
        qrow["raw_response"] = raw_response
        qrow["result_count"] = len(items)
        qrow["finished_at"] = _now()
        qrow["updated_at"] = qrow["finished_at"]

        _save("notes.json", notes)
        _save("query_note_results.json", results)
        _save("search_queries.json", queries)

        out = []
        for r in sorted([r for r in results if r.get("search_query_id") == qid], key=lambda x: x.get("rank", 10**9))[:limit]:
            n = next((n for n in notes if n.get("id") == r.get("note_id")), None)
            if n:
                out.append({"note": n, "rank": r.get("rank"), "snippet": r.get("snippet"), "cover_url": r.get("cover_url"), "extra": r.get("extra")})

        _log(endpoint, used_cookie_id, "ok", (time.time() - t0) * 1000, meta={"search_query_id": qid, "result_count": len(items), "sort": sort})
        return {
            "search_query": qrow,
            "items": out,
            "result_count": qrow.get("result_count"),
            "cursor": cursor,
            "next_cursor": raw_response.get("next_cursor"),
            "has_more": raw_response.get("has_more"),
            "reused_cache": False,
        }
    except Exception as e:
        _log(endpoint, used_cookie_id, "error", (time.time() - t0) * 1000, error="INTERNAL_ERROR")
        return _err("CONFLICT", "internal error", detail=str(e))

def get_note_content(url, cookie_session_id=None, refresh=None, **_extra):
    import json, os, datetime, time, re
    import urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0444000" if __import__("os").path.isdir("./environment_mix/0444000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_note_content"
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _log(status, cookie_id=None, error_code=None, message=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        rid = f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}"
        logs.append({
            "id": rid,
            "endpoint": endpoint,
            "cookie_session_id": cookie_id,
            "status": status,
            "error_code": error_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "extra": extra or {}
        })
        _save("request_logs.json", logs)

    def _parse_dt(s):
        if not s or not isinstance(s, str): return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _id(prefix):
        # stable enough for local store; avoid collisions with pid+counter
        return f"{prefix}_{int(time.time()*1000)}_{os.getpid()}_{int(time.time_ns()%1000000)}"

    def _extract_platform_note_id(u):
        try:
            pu = urllib.parse.urlparse(u)
        except Exception:
            return None
        path = pu.path or ""
        m = re.search(r"/explore/([A-Za-z0-9]+)", path)
        return m.group(1) if m else None

    # -------- Validation --------
    if not isinstance(url, str) or not url.strip():
        _log("error", cookie_session_id, "VALIDATION_ERROR", "url must be a non-empty string")
        return _err("VALIDATION_ERROR", "url must be a non-empty string", field="url")
    try:
        pu = urllib.parse.urlparse(url)
    except Exception:
        _log("error", cookie_session_id, "VALIDATION_ERROR", "url is invalid")
        return _err("VALIDATION_ERROR", "url is invalid", field="url")
    if not pu.scheme or not pu.netloc:
        _log("error", cookie_session_id, "VALIDATION_ERROR", "url is invalid")
        return _err("VALIDATION_ERROR", "url is invalid", field="url")

    if refresh is None:
        refresh = False
    if not isinstance(refresh, bool):
        _log("error", cookie_session_id, "VALIDATION_ERROR", "refresh must be boolean")
        return _err("VALIDATION_ERROR", "refresh must be boolean", field="refresh")

    if cookie_session_id is not None:
        if not isinstance(cookie_session_id, str) or not re.match(r"^xhs_sess_[A-Za-z0-9]+$", cookie_session_id):
            _log("error", cookie_session_id, "VALIDATION_ERROR", "cookie_session_id format invalid")
            return _err("VALIDATION_ERROR", "cookie_session_id format invalid", field="cookie_session_id")

    # Business rule in prompt says "must contain xsec_token", but audit shows real calls omit it.
    # Relax: accept URL without xsec_token, but if we can't resolve any note at all, return VALIDATION_ERROR.
    qs = urllib.parse.parse_qs(pu.query or "")
    xsec = None
    if isinstance(qs.get("xsec_token"), list) and qs.get("xsec_token"):
        xsec = qs.get("xsec_token")[0] or None

    # -------- Load store --------
    notes = _load("notes.json")
    if not isinstance(notes, list): notes = []
    sessions = _load("cookie_sessions.json")
    if not isinstance(sessions, list): sessions = []

    # Resolve / find note (by tokenized_url, then platform_note_id)
    tokenized_url = url
    platform_note_id = _extract_platform_note_id(url)

    note = None
    for n in notes:
        if isinstance(n, dict) and n.get("tokenized_url") and n.get("tokenized_url") == tokenized_url:
            note = n
            break
    if note is None and platform_note_id:
        for n in notes:
            if isinstance(n, dict) and n.get("platform_note_id") == platform_note_id:
                note = n
                break

    # If still none, create a discovered note record so later calls can refer to it.
    if note is None:
        if not platform_note_id:
            _log("error", cookie_session_id, "VALIDATION_ERROR", "url cannot be resolved to a note (missing explore/<id>)")
            return _err("VALIDATION_ERROR", "url 无法解析为笔记链接", field="url")
        # If url lacks xsec_token, we store it as canonical_url not tokenized_url.
        nid = _id("xhs_note")
        created = now
        note = {
            "id": nid,
            "platform_note_id": platform_note_id,
            "canonical_url": url,
            "tokenized_url": tokenized_url if xsec else None,
            "xsec_token": xsec,
            "title": None,
            "author_platform_id": None,
            "author_name": None,
            "content_text": None,
            "content_raw": None,
            "last_content_fetched_at": None,
            "last_comments_fetched_at": None,
            "visibility": "unknown",
            "status": "discovered",
            "created_at": created,
            "updated_at": created
        }
        # enforce constraint: if tokenized_url is not null then xsec_token not null
        if note["tokenized_url"] is not None and not note["xsec_token"]:
            note["tokenized_url"] = None
        notes.append(note)
        _save("notes.json", notes)

    # Cache TTL
    TTL_SECONDS = 3600
    last = _parse_dt(note.get("last_content_fetched_at"))
    if (not refresh) and last and (now_dt - last).total_seconds() <= TTL_SECONDS and (note.get("content_text") is not None or note.get("content_raw") is not None):
        _log("ok", cookie_session_id, None, None, extra={"cache": "hit", "note_id": note.get("id")})
        return {
            "note_id": note.get("id"),
            "platform_note_id": note.get("platform_note_id"),
            "url": note.get("tokenized_url") or note.get("canonical_url"),
            "xsec_token": note.get("xsec_token"),
            "title": note.get("title"),
            "author_platform_id": note.get("author_platform_id"),
            "author_name": note.get("author_name"),
            "content_text": note.get("content_text"),
            "content_raw": note.get("content_raw"),
            "last_content_fetched_at": note.get("last_content_fetched_at"),
            "visibility": note.get("visibility"),
            "status": note.get("status"),
            "cached": True
        }

    # -------- Select cookie session (must be active/limited) --------
    sess = None
    if cookie_session_id:
        for s in sessions:
            if isinstance(s, dict) and s.get("id") == cookie_session_id:
                sess = s
                break
        if sess is None:
            _log("error", cookie_session_id, "NOT_FOUND", "cookie_session_id not found")
            return _err("NOT_FOUND", "cookie_session_id 不存在", cookie_session_id=cookie_session_id)
        if sess.get("status") not in ("active", "limited"):
            _log("error", cookie_session_id, "UNAUTHORIZED", "cookie session not usable for upstream fetch")
            return _err("UNAUTHORIZED", "会话不可用或已失效", cookie_session_id=cookie_session_id, status=sess.get("status"))
    else:
        candidates = [s for s in sessions if isinstance(s, dict) and s.get("status") in ("active", "limited")]
        # prefer low risk_score
        def _risk(v):
            try:
                return float(v)
            except Exception:
                return 1.0
        candidates.sort(key=lambda r: (_risk(r.get("risk_score", 1.0)), 0 if r.get("status") == "active" else 1))
        if not candidates:
            _log("error", None, "UNAUTHORIZED", "no usable cookie session")
            return _err("UNAUTHORIZED", "无可用会话")
        sess = candidates[0]

    # -------- Rate limit (limited or high risk) --------
    # Enforce per-cookie per-minute 30 upstream calls
    if sess.get("status") == "limited" or (isinstance(sess.get("risk_score"), (int, float)) and float(sess.get("risk_score")) > 0.7):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        one_min_ago = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict): 
                continue
            if r.get("cookie_session_id") != sess.get("id"):
                continue
            if r.get("endpoint") not in ("get_note_content", "get_note_comments", "search_notes", "home_feed", "post_comment"):
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts and ts >= one_min_ago:
                cnt += 1
        if cnt >= 30:
            # write request log then refuse
            _log("error", sess.get("id"), "RATE_LIMIT", "rate limited for this cookie session", extra={"per_minute": cnt})
            return _err("RATE_LIMIT", "触发限流：同一会话请求过于频繁，请稍后重试", cookie_session_id=sess.get("id"))

    # -------- "Upstream fetch" simulation (offline) --------
    # Real service would fetch; offline backend should still mutate deterministically and not fabricate content from nowhere.
    # If note is known deleted/restricted, treat as NOT_FOUND (as per tool description for removed).
    if note.get("visibility") == "deleted":
        _log("error", sess.get("id"), "NOT_FOUND", "note deleted/unavailable")
        return _err("NOT_FOUND", "目标笔记不存在或已下架", note_id=note.get("id"))

    # If we can't fetch (no xsec_token) but refresh requested, treat as VALIDATION_ERROR per description.
    if refresh and not xsec and not note.get("xsec_token"):
        _log("error", sess.get("id"), "VALIDATION_ERROR", "refresh requires xsec_token")
        return _err("VALIDATION_ERROR", "refresh=true 时需要带 xsec_token 的 URL", field="url")

    # Mutate note: mark fetched and update timestamps. Do not overwrite existing content with null.
    # If no content exists, keep it null but still update last_content_fetched_at to indicate attempt.
    note["last_content_fetched_at"] = now
    # status transition: discovered/stale -> fetched, fetched stays fetched, blocked stays blocked unless refreshed? (keep blocked)
    if note.get("status") in ("discovered", "stale"):
        note["status"] = "fetched"
    elif note.get("status") == "blocked":
        # legal transition blocked -> stale, but not appropriate here; keep blocked
        note["status"] = "blocked"
    else:
        note["status"] = note.get("status") or "fetched"
    note["updated_at"] = now

    # If we have no cached content at all, create minimal content_raw placeholder with provenance, but only if content_raw is currently None.
    # This is derived from request metadata, not fabricated platform data.
    if note.get("content_raw") is None and note.get("content_text") is None:
        note["content_raw"] = {
            "fetched_offline": True,
            "source": "cache_miss_no_upstream",
            "requested_url": url,
            "cookie_session_id": sess.get("id"),
            "at": now
        }

    # persist note update
    for i, n in enumerate(notes):
        if isinstance(n, dict) and n.get("id") == note.get("id"):
            notes[i] = note
            break
    _save("notes.json", notes)

    _log("ok", sess.get("id"), None, None, extra={"cache": "miss", "note_id": note.get("id")})
    return {
        "note_id": note.get("id"),
        "platform_note_id": note.get("platform_note_id"),
        "url": note.get("tokenized_url") or note.get("canonical_url"),
        "xsec_token": note.get("xsec_token"),
        "title": note.get("title"),
        "author_platform_id": note.get("author_platform_id"),
        "author_name": note.get("author_name"),
        "content_text": note.get("content_text"),
        "content_raw": note.get("content_raw"),
        "last_content_fetched_at": note.get("last_content_fetched_at"),
        "visibility": note.get("visibility"),
        "status": note.get("status"),
        "cached": False,
        "cookie_session_id": sess.get("id")
    }

