        "comments": page,
        "total": len(rows),
        "has_more": next_cursor is not None,
        "next_cursor": next_cursor,
        "cached": False,
        "cookie_session_id": sess.get("id")
    }

def post_comment(note_id, comment, cookie_session_id=None, parent_platform_comment_id=None, dry_run=None, **_extra):
    import json, os, datetime, time, re, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0444000" if __import__("os").path.isdir("./environment_mix/0444000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "post_comment"
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _log(status, cookie_id=None, error_code=None, message=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        rid = f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}"
        logs.append({
            "id": rid,
            "endpoint": endpoint,
            "cookie_session_id": cookie_id,
            "status": status,
            "error_code": error_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "extra": extra or {}
        })
        _save("request_logs.json", logs)

    def _dt_parse(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix, rows):
        seed = f"{prefix}|{time.time_ns()}|{os.getpid()}|{len(rows)+1}|{random.random()}"
        h = hashlib.sha1(seed.encode("utf-8")).hexdigest()
        return f"{prefix}_{h[:26]}"

    def _minute_bucket(ts):
        return ts.replace(second=0, microsecond=0)

    def _enforce_rate_limit_for_session(sess_id, sess_row):
        # Rule: when status='limited' OR risk_score>0.7 => max 30 upstream requests per minute
        st = sess_row.get("status")
        risk = sess_row.get("risk_score", 0)
        try:
            risk = float(risk)
        except Exception:
            risk = 0.0
        limited = (st == "limited") or (risk > 0.7)
        if not limited:
            return None  # no limit enforcement needed

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now_local = now_dt
        bucket = _minute_bucket(now_local)
        count = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("cookie_session_id") != sess_id:
                continue
            if r.get("endpoint") not in ("home_feed", "search_notes", "get_note_content", "get_note_comments", "post_comment", "check_cookie"):
                continue
            ts = r.get("timestamp")
            dt = _dt_parse(ts)
            if not dt:
                continue
            if _minute_bucket(dt) == bucket:
                # count only those that likely correspond to upstream interactions; in this simplified service,
                # assume all these endpoints may hit upstream.
                count += 1

        if count >= 30:
            return _err("RATE_LIMIT", "触发限流：同一会话请求过于频繁，请稍后重试", cookie_session_id=sess_id, limit_per_minute=30)
        return None

    def _pick_cookie_session(sessions, wanted_id=None):
        usable = []
        for s in sessions:
            if not isinstance(s, dict):
                continue
            st = s.get("status")
            if st not in ("active", "limited"):
                continue
            # For posting, an active/limited session that last_check_ok is True is preferred,
            # but allow missing last_check_ok field (treat unknown as usable).
            lco = s.get("last_check_ok")
            if lco is False:
                continue
            risk = s.get("risk_score", 0)
            try:
                risk = float(risk)
            except Exception:
                risk = 0.0
            usable.append((risk, s))

        if wanted_id is not None:
            for _, s in usable:
                if s.get("id") == wanted_id:
                    return s
            return None

        usable.sort(key=lambda x: (x[0], x[1].get("updated_at") or "", x[1].get("id") or ""))
        return usable[0][1] if usable else None

    try:
        # Validate note_id format per tool schema
        if not isinstance(note_id, str) or not note_id.strip():
            _log("error", None, "VALIDATION_ERROR", "note_id invalid", extra={"field": "note_id"})
            return _err("VALIDATION_ERROR", "note_id 不能为空且必须为 string", field="note_id")
        note_id = note_id.strip()
        if not re.match(r"^xhs_note_[A-Za-z0-9]+$", note_id):
            _log("error", None, "VALIDATION_ERROR", "note_id format invalid", extra={"field": "note_id", "note_id": note_id})
            return _err("VALIDATION_ERROR", "note_id 格式非法，必须为 xhs_note_...", field="note_id", note_id=note_id)

        # IMPORTANT: accept non-string comment per audit. Coerce to string like real services often do.
        if comment is None:
            _log("error", None, "VALIDATION_ERROR", "comment missing", extra={"field": "comment"})
            return _err("VALIDATION_ERROR", "comment 不能为空", field="comment")
        if isinstance(comment, (dict, list)):
            _log("error", None, "VALIDATION_ERROR", "comment type invalid", extra={"field": "comment"})
            return _err("VALIDATION_ERROR", "comment 必须为可序列化为文本的标量（string/number/bool）", field="comment")
        if not isinstance(comment, str):
            comment = str(comment)
        comment = comment.strip()
        # Business rule: length 1..500
        if len(comment) < 1 or len(comment) > 500:
            _log("error", None, "VALIDATION_ERROR", "comment length invalid", extra={"field": "comment", "length": len(comment)})
            return _err("VALIDATION_ERROR", "违反业务规则：content length between 1 and 500", field="comment", length=len(comment))

        if parent_platform_comment_id is not None and not isinstance(parent_platform_comment_id, str):
            _log("error", None, "VALIDATION_ERROR", "parent_platform_comment_id must be string", extra={"field": "parent_platform_comment_id"})
            return _err("VALIDATION_ERROR", "parent_platform_comment_id 必须为 string", field="parent_platform_comment_id")

        if dry_run is not None and not isinstance(dry_run, bool):
            _log("error", None, "VALIDATION_ERROR", "dry_run must be boolean", extra={"field": "dry_run"})
            return _err("VALIDATION_ERROR", "dry_run 必须为 boolean", field="dry_run")

        if cookie_session_id is not None:
            if not isinstance(cookie_session_id, str) or not cookie_session_id.strip():
                _log("error", None, "VALIDATION_ERROR", "cookie_session_id invalid", extra={"field": "cookie_session_id"})
                return _err("VALIDATION_ERROR", "cookie_session_id 必须为 string", field="cookie_session_id")
            cookie_session_id = cookie_session_id.strip()
            if not re.match(r"^xhs_sess_[A-Za-z0-9]+$", cookie_session_id):
                _log("error", None, "VALIDATION_ERROR", "cookie_session_id format invalid", extra={"field": "cookie_session_id", "cookie_session_id": cookie_session_id})
                return _err("VALIDATION_ERROR", "cookie_session_id 格式非法，必须为 xhs_sess_...", field="cookie_session_id", cookie_session_id=cookie_session_id)

        notes = _load("notes.json")
        if not isinstance(notes, list):
            notes = []
        note_row = None
        for n in notes:
            if isinstance(n, dict) and n.get("id") == note_id:
                note_row = n
                break
        if note_row is None:
            _log("error", cookie_session_id, "NOT_FOUND", "note not found", extra={"note_id": note_id})
            return _err("NOT_FOUND", "指定笔记缓存记录不存在", note_id=note_id)

        # Business rule: must validate notes.platform_note_id exists
        platform_note_id = note_row.get("platform_note_id")
        if not isinstance(platform_note_id, str) or not platform_note_id.strip():
            _log("error", cookie_session_id, "CONFLICT", "platform_note_id missing", extra={"note_id": note_id})
            return _err("CONFLICT", "目标笔记缺少 platform_note_id，无法发布评论（规则：必须校验 note_id 对应 notes.platform_note_id 存在）", note_id=note_id)

        # Pick / validate cookie session
        sessions = _load("cookie_sessions.json")
        if not isinstance(sessions, list):
            sessions = []

        if cookie_session_id is not None:
            sess = None
            for s in sessions:
                if isinstance(s, dict) and s.get("id") == cookie_session_id:
                    sess = s
                    break
            if sess is None:
                _log("error", cookie_session_id, "NOT_FOUND", "cookie session not found", extra={"cookie_session_id": cookie_session_id})
                return _err("NOT_FOUND", "指定 cookie_session 不存在", cookie_session_id=cookie_session_id)
            if sess.get("status") not in ("active", "limited"):
                _log("error", cookie_session_id, "UNAUTHORIZED", "cookie session not usable", extra={"status": sess.get("status")})
                return _err("UNAUTHORIZED", "会话不可用（需为 active/limited）", cookie_session_id=cookie_session_id, status=sess.get("status"))
            if sess.get("last_check_ok") is False:
                _log("error", cookie_session_id, "UNAUTHORIZED", "cookie last_check_ok=false", extra={"last_check_error": sess.get("last_check_error")})
                return _err("UNAUTHORIZED", "会话疑似失效或无权限", cookie_session_id=cookie_session_id, reason=sess.get("last_check_error"))
        else:
            sess = _pick_cookie_session(sessions, None)
            if sess is None:
                _log("error", None, "UNAUTHORIZED", "no usable cookie session", extra={})
                return _err("UNAUTHORIZED", "没有可用的 cookie 会话（需存在 status=active/limited 的会话）")
            cookie_session_id = sess.get("id")

        # Rate limit precheck (for dry_run also return rate limit result as it affects ability to post)
        rl_err = _enforce_rate_limit_for_session(cookie_session_id, sess)
        if rl_err:
            # Must be observable in search_queries for those tools; for post_comment, log request and return RATE_LIMIT
            _log("error", cookie_session_id, "RATE_LIMIT", rl_err["error"]["message"], extra={"cookie_session_id": cookie_session_id})
            return rl_err

        # If note visibility indicates deleted/restricted, treat as conflict for "not allowed to comment"
        vis = note_row.get("visibility")
        if vis in ("deleted",):
            _log("error", cookie_session_id, "CONFLICT", "note deleted", extra={"visibility": vis})
            return _err("CONFLICT", "目标笔记已删除，无法评论", note_id=note_id)
        if vis in ("restricted",):
            _log("error", cookie_session_id, "CONFLICT", "note restricted", extra={"visibility": vis})
            return _err("CONFLICT", "目标笔记受限，可能不允许评论", note_id=note_id)

        # Duplicate comment check (platform-side duplicate often conflict): if same note_id + content recently posted by same session
        comments = _load("note_comments.json")
        if not isinstance(comments, list):
            comments = []
        for c in comments:
            if not isinstance(c, dict):
                continue
            if c.get("note_id") != note_id:
                continue
            if c.get("source") != "posted":
                continue
            if c.get("posted_by_cookie_session_id") != cookie_session_id:
                continue
            if (c.get("content") or "").strip() == comment and c.get("status") in ("pending_post", "post_succeeded", "visible"):
                _log("error", cookie_session_id, "CONFLICT", "duplicate comment", extra={"existing_comment_id": c.get("id")})
                return _err("CONFLICT", "评论被判定为重复或已在发布中", existing_comment_id=c.get("id"))

        # Create note_comments row (pending_post). Must persist even in dry_run? description says dry_run won't actually post,
        # but still returns session and validation conclusion. Realistic behavior: do not create row on dry_run.
        if dry_run is True:
            _log("success", cookie_session_id, None, None, extra={"dry_run": True, "note_id": note_id})
            return {
                "dry_run": True,
                "ok": True,
                "cookie_session": sess,
                "validation": {"can_post": True},
                "note": {"id": note_id, "platform_note_id": platform_note_id}
            }

        new_id = _gen_id("xhs_cmt", comments)
        row = {
            "id": new_id,
            "note_id": note_id,
            "platform_comment_id": None,
            "parent_platform_comment_id": parent_platform_comment_id,
            "author_platform_id": None,
            "author_name": None,
            "content": comment,
            "source": "posted",
            "posted_by_cookie_session_id": cookie_session_id,
            "status": "pending_post",
            "post_error_code": None,
            "post_error_message": None,
            "commented_at": None,
            "created_at": now,
            "updated_at": now
        }
        comments.append(row)
        _save("note_comments.json", comments)

        # Simulate upstream publish result deterministically-ish based on risk/status
        # - If session seems expired/bad -> UNAUTHORIZED
        # - If risk high -> sometimes RISK_CONTROL
        # - Otherwise success
        st = sess.get("status")
        risk = sess.get("risk_score", 0)
        try:
            risk = float(risk)
        except Exception:
            risk = 0.0

        def _update_row(r):
            r["updated_at"] = now

        # Some conditions for failure
        if sess.get("last_check_ok") is False or st not in ("active", "limited"):
            row["status"] = "post_failed"
            row["post_error_code"] = "COOKIE_EXPIRED"
            row["post_error_message"] = "会话失效，发布失败"
            _update_row(row)
            _save("note_comments.json", comments)
            _log("error", cookie_session_id, "UNAUTHORIZED", row["post_error_message"], extra={"comment_id": new_id})
            return _err("UNAUTHORIZED", "会话失效/无发布权限", cookie_session_id=cookie_session_id, post_error_code=row["post_error_code"], comment_id=new_id)

        # If limited/high risk, probabilistic RISK_CONTROL (but deterministic per minute+content hash)
        h = int(hashlib.sha1(f"{cookie_session_id}|{platform_note_id}|{comment}|{now[:16]}".encode("utf-8")).hexdigest(), 16)
        if st == "limited" or risk > 0.7:
            if (h % 5) == 0:
                row["status"] = "post_failed"
                row["post_error_code"] = "RISK_CONTROL"
                row["post_error_message"] = "触发风控，评论发布被拦截，请稍后再试"
                _update_row(row)
                _save("note_comments.json", comments)
                _log("error", cookie_session_id, "UNAUTHORIZED", row["post_error_message"], extra={"comment_id": new_id})
                return _err("UNAUTHORIZED", "被风控拦截", cookie_session_id=cookie_session_id, post_error_code=row["post_error_code"], comment_id=new_id)

        # Success
        platform_comment_id = hashlib.sha1(f"pcid|{new_id}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24]
        row["platform_comment_id"] = platform_comment_id
        row["commented_at"] = now
        row["status"] = "post_succeeded"
        _update_row(row)
        _save("note_comments.json", comments)

        _log("success", cookie_session_id, None, None, extra={"comment_id": new_id, "note_id": note_id})
        return {
            "comment": row,
            "cookie_session": sess,
            "upstream": {"ok": True, "platform_comment_id": platform_comment_id}
        }

    except Exception as e:
        _log("error", cookie_session_id, "UPSTREAM_UNAVAILABLE", "internal error", extra={"detail": str(e)})
        return _err("UPSTREAM_UNAVAILABLE", "服务内部错误", detail=str(e))

def list_cookie_sessions(status=None, label=None, user_id_hint=None, page_size=None, page_token=None, order_by=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0444000" if __import__("os").path.isdir("./environment_mix/0444000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, message=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + hashlib.sha256(f"list_cookie_sessions|{now}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": "list_cookie_sessions",
            "credential": None,
            "status": status_s,
            "message": message,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": now,
            "extra": extra or {}
        })
        _save("request_logs.json", logs)

    allowed_status = {"active", "limited", "expired", "banned", "disabled"}
    allowed_order = {"created_at_desc", "created_at_asc", "updated_at_desc", "updated_at_asc", "last_checked_at_desc"}

    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log("error", "invalid status filter")
            return _err("VALIDATION_ERROR", "invalid status")
    if label is not None and not isinstance(label, str):
        _log("error", "label must be string")
        return _err("VALIDATION_ERROR", "label must be a string")
    if user_id_hint is not None and not isinstance(user_id_hint, str):
        _log("error", "user_id_hint must be string")
        return _err("VALIDATION_ERROR", "user_id_hint must be a string")

    if page_size is None:
        page_size = 20
    if not isinstance(page_size, int) or page_size < 1 or page_size > 100:
        _log("error", "page_size out of range")
        return _err("VALIDATION_ERROR", "page_size must be between 1 and 100")

    if page_token is not None and not isinstance(page_token, str):
        _log("error", "page_token must be string")
        return _err("VALIDATION_ERROR", "page_token must be a string")

    if order_by is None:
        order_by = "updated_at_desc"
    if not isinstance(order_by, str) or order_by not in allowed_order:
        _log("error", "order_by invalid")
        return _err("VALIDATION_ERROR", "order_by invalid")

    rows = _load("cookie_sessions.json")
    if not isinstance(rows, list):
        rows = []

    def _match(r):
        if not isinstance(r, dict):
            return False
        if status is not None and r.get("status") != status:
            return False
        if label is not None and r.get("label") != label:
            return False
        if user_id_hint is not None and r.get("user_id_hint") != user_id_hint:
            return False
        return True

    filtered = [r for r in rows if _match(r)]

    def _ts(v):
        return v or ""

    if order_by == "created_at_desc":
        filtered.sort(key=lambda r: _ts(r.get("created_at")), reverse=True)
    elif order_by == "created_at_asc":
        filtered.sort(key=lambda r: _ts(r.get("created_at")))
    elif order_by == "updated_at_desc":
        filtered.sort(key=lambda r: _ts(r.get("updated_at")), reverse=True)
    elif order_by == "updated_at_asc":
        filtered.sort(key=lambda r: _ts(r.get("updated_at")))
    elif order_by == "last_checked_at_desc":
        filtered.sort(key=lambda r: _ts(r.get("last_checked_at")), reverse=True)

    offset = 0
    if page_token:
        try:
            offset = int(page_token)
            if offset < 0:
                raise ValueError()
        except Exception:
            _log("error", "page_token invalid")
            return _err("VALIDATION_ERROR", "page_token invalid")

    total = len(filtered)
    items = filtered[offset: offset + page_size]
    next_offset = offset + len(items)
    has_more = next_offset < total
    next_token = str(next_offset) if has_more else None

    _log("ok", "ok", extra={"returned": len(items), "total": total})
    return {
        "items": items,
        "pagination": {
            "page_size": page_size,
            "page_token": page_token,
            "next_page_token": next_token,
            "has_more": has_more,
            "total": total
        }
    }

def create_cookie_session(label=None, cookie_jar=None, user_id_hint=None, status=None, disabled_reason=None, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0444000" if __import__("os").path.isdir("./environment_mix/0444000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, message=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + hashlib.sha256(f"create_cookie_session|{now}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": "create_cookie_session",
            "credential": None,
            "status": status_s,
            "message": message,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": now,
            "extra": extra or {}
        })
        _save("request_logs.json", logs)

    # Validation
    if label is not None and not isinstance(label, str):
        _log("error", "label must be string")
        return _err("VALIDATION_ERROR", "label must be a string")
    if user_id_hint is not None and not isinstance(user_id_hint, str):
        _log("error", "user_id_hint must be string")
        return _err("VALIDATION_ERROR", "user_id_hint must be a string")

    allowed_status = {"active", "limited", "expired", "banned", "disabled"}
    if status is None:
        status = "active"
    if not isinstance(status, str) or status not in allowed_status:
        _log("error", "status invalid")
        return _err("VALIDATION_ERROR", "status invalid")

    if status == "disabled":
        if disabled_reason is None or not isinstance(disabled_reason, str) or not disabled_reason.strip():
            _log("error", "disabled_reason required when status=disabled")
            return _err("VALIDATION_ERROR", "disabled_reason is required when status=disabled")
    else:
        if disabled_reason is not None and not isinstance(disabled_reason, str):
            _log("error", "disabled_reason must be string")
            return _err("VALIDATION_ERROR", "disabled_reason must be a string")

    if not isinstance(cookie_jar, str) or not cookie_jar.strip():
        _log("error", "cookie_jar must be non-empty string")
        return _err("VALIDATION_ERROR", "cookie_jar must be a non-empty string")

    # Parse cookie_jar: accept JSON string or raw cookie string "a=b; c=d"
    parsed = None
    s = cookie_jar.strip()
    if s.startswith("{") or s.startswith("["):
        try:
            parsed = json.loads(s)
        except Exception:
            _log("error", "cookie_jar cannot be parsed as JSON")
            return _err("VALIDATION_ERROR", "cookie_jar JSON parse failed")
    else:
        jar = {}
        parts = [p.strip() for p in s.split(";") if p.strip()]
        for p in parts:
            if "=" in p:
                k, v = p.split("=", 1)
                k = k.strip()
                v = v.strip()
                if k:
                    jar[k] = v
        parsed = {"cookies": jar, "raw": s}

    # "判定为不可用登录态" -> if no meaningful cookies present
    ok = False
    if isinstance(parsed, dict):
        if "cookies" in parsed and isinstance(parsed.get("cookies"), dict) and len(parsed.get("cookies")) > 0:
            ok = True
        elif len(parsed.keys()) > 0:
            ok = True
    elif isinstance(parsed, list) and len(parsed) > 0:
        ok = True

    if not ok:
        _log("error", "cookie_jar appears unusable")
        return _err("UNAUTHORIZED", "cookie_jar appears unusable")

    rows = _load("cookie_sessions.json")
    if not isinstance(rows, list):
        rows = []

    # Create id
    cid = "xhs_sess_" + hashlib.sha256(f"{time.time_ns()}|{s}".encode("utf-8")).hexdigest()[:16]

    # Ensure constraints risk_score within [0,1]; initialize 0
    row = {
        "id": cid,
        "label": label,
        "cookie_jar": parsed,
        "user_id_hint": user_id_hint,
        "last_checked_at": None,
        "last_check_ok": True if status in ("active", "limited") else False,
        "last_check_error": None if status in ("active", "limited") else "not_checked_or_inactive",
        "risk_score": 0.0,
        "status": status,
        "disabled_reason": disabled_reason if status == "disabled" else None,
        "created_at": now,
        "updated_at": now
    }

    # Enforce constraints: last_check_ok=true implies status in ('active','limited')
    if row["last_check_ok"] and row["status"] not in ("active", "limited"):
        row["last_check_ok"] = False
        row["last_check_error"] = "status_not_active"

    # status in ('expired','banned') implies last_check_ok=false
    if row["status"] in ("expired", "banned"):
        row["last_check_ok"] = False
        row["last_check_error"] = row["last_check_error"] or "status_" + row["status"]

    rows.append(row)
    _save("cookie_sessions.json", rows)

    _log("ok", "created", extra={"cookie_session_id": cid})
    return {"cookie_session": row}

def update_cookie_session(cookie_session_id, label=None, user_id_hint=None, risk_score=None, status=None, disabled_reason=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0444000" if __import__("os").path.isdir("./environment_mix/0444000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- observable service dynamics: request log + rate limit (best-effort, schema may not include) ----
    def _log(endpoint, status_code, cookie_session_used=None, error_code=None, message=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": endpoint,
            "cookie_session_id": cookie_session_used,
            "status": status_code,
            "error_code": error_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        }
        if extra is not None:
            row["extra"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    # mutation endpoints do not represent upstream calls; still enforce session-local limit if a session is implied.
    # This tool targets a specific session, so use it for rate limiting if it exists.
    def _rate_limited_for_session(sess):
        if not sess:
            return False
        limited = (sess.get("status") == "limited") or (isinstance(sess.get("risk_score"), (int, float)) and sess.get("risk_score", 0) > 0.7)
        if not limited:
            return False
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return False
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        sid = sess.get("id")
        for r in logs:
            if r.get("cookie_session_id") != sid:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        return cnt >= 30

    endpoint = "update_cookie_session"

    # ---- validation ----
    if not isinstance(cookie_session_id, str) or not re.match(r"^xhs_sess_[A-Za-z0-9]+$", cookie_session_id):
        _log(endpoint, 400, None, "VALIDATION_ERROR", "cookie_session_id format invalid")
        return _err("VALIDATION_ERROR", "cookie_session_id 格式非法", field="cookie_session_id")

    if label is not None and not isinstance(label, str):
        _log(endpoint, 400, cookie_session_id, "VALIDATION_ERROR", "label must be string")
        return _err("VALIDATION_ERROR", "label 必须为字符串", field="label")
    if user_id_hint is not None and not isinstance(user_id_hint, str):
        _log(endpoint, 400, cookie_session_id, "VALIDATION_ERROR", "user_id_hint must be string")
        return _err("VALIDATION_ERROR", "user_id_hint 必须为字符串", field="user_id_hint")
    if risk_score is not None:
        if not isinstance(risk_score, (int, float)) or isinstance(risk_score, bool):
            _log(endpoint, 400, cookie_session_id, "VALIDATION_ERROR", "risk_score must be number")
            return _err("VALIDATION_ERROR", "risk_score 必须为数字", field="risk_score")
        if risk_score < 0 or risk_score > 1:
            _log(endpoint, 400, cookie_session_id, "VALIDATION_ERROR", "risk_score out of range")
            return _err("VALIDATION_ERROR", "risk_score 必须在 0 到 1 之间", field="risk_score")
    allowed_status = ["active", "limited", "expired", "banned", "disabled"]
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log(endpoint, 400, cookie_session_id, "VALIDATION_ERROR", "status invalid")
            return _err("VALIDATION_ERROR", "status 非法", field="status", allowed=allowed_status)
    if disabled_reason is not None and not isinstance(disabled_reason, str):
        _log(endpoint, 400, cookie_session_id, "VALIDATION_ERROR", "disabled_reason must be string")
        return _err("VALIDATION_ERROR", "disabled_reason 必须为字符串", field="disabled_reason")

    sessions = _load("cookie_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    sess = None
    idx = None
    for i, s in enumerate(sessions):
        if isinstance(s, dict) and s.get("id") == cookie_session_id:
            sess = s
            idx = i
            break

    if sess is None:
        _log(endpoint, 404, cookie_session_id, "NOT_FOUND", "cookie session not found")
        return _err("NOT_FOUND", "cookie_session_id 不存在", cookie_session_id=cookie_session_id)

    if _rate_limited_for_session(sess):
        _log(endpoint, 429, cookie_session_id, "RATE_LIMIT", "session rate limited")
        return _err("RATE_LIMIT", "该会话处于 limited/高风险状态，1 分钟内请求次数已达上限")

    transitions = {
        "active": ["limited", "expired", "banned", "disabled"],
        "limited": ["active", "expired", "banned", "disabled"],
        "expired": ["active", "disabled"],
        "banned": ["disabled"],
        "disabled": ["active"],
    }

    # ---- apply updates ----
    changed = False
    new_sess = dict(sess)

    if label is not None and label != new_sess.get("label"):
        new_sess["label"] = label
        changed = True
    if user_id_hint is not None and user_id_hint != new_sess.get("user_id_hint"):
        new_sess["user_id_hint"] = user_id_hint
        changed = True
    if risk_score is not None and risk_score != new_sess.get("risk_score"):
        new_sess["risk_score"] = float(risk_score)
        changed = True

    if status is not None:
        cur = new_sess.get("status")
        if cur != status:
            if cur not in transitions or status not in transitions.get(cur, []):
                _log(endpoint, 409, cookie_session_id, "CONFLICT", "invalid status transition", extra={"from": cur, "to": status})
                return _err("CONFLICT", "不允许的状态流转", from_status=cur, to_status=status)
            new_sess["status"] = status
            changed = True

    # disabled_reason rules: when status=disabled, must be non-null
    if status is not None:
        effective_status = status
    else:
        effective_status = new_sess.get("status")

    if effective_status == "disabled":
        # if caller supplied disabled_reason, use it; else ensure it exists already
        if disabled_reason is not None:
            if disabled_reason.strip() == "":
                _log(endpoint, 400, cookie_session_id, "VALIDATION_ERROR", "disabled_reason required when disabled")
                return _err("VALIDATION_ERROR", "status=disabled 时 disabled_reason 不能为空", field="disabled_reason")
            if disabled_reason != new_sess.get("disabled_reason"):
                new_sess["disabled_reason"] = disabled_reason
                changed = True
        else:
            if new_sess.get("disabled_reason") in (None, ""):
                _log(endpoint, 400, cookie_session_id, "VALIDATION_ERROR", "disabled_reason missing when disabled")
                return _err("VALIDATION_ERROR", "status=disabled 时必须提供 disabled_reason", field="disabled_reason")
    else:
        # when not disabled, caller may clear; if provided, set to it (including empty -> clear)
        if disabled_reason is not None and disabled_reason != new_sess.get("disabled_reason"):
            if disabled_reason.strip() == "":
                new_sess["disabled_reason"] = None
            else:
                new_sess["disabled_reason"] = disabled_reason
            changed = True

    # other constraints:
    # - last_check_ok=true implies status in ('active','limited')
    # - status in ('expired','banned') implies last_check_ok=false
    lco = new_sess.get("last_check_ok")
    if lco is True and effective_status not in ("active", "limited"):
        _log(endpoint, 409, cookie_session_id, "CONFLICT", "constraint last_check_ok/status violated")
        return _err("CONFLICT", "约束冲突：last_check_ok=true 时 status 只能为 active/limited")
    if effective_status in ("expired", "banned") and lco is True:
        _log(endpoint, 409, cookie_session_id, "CONFLICT", "constraint status implies last_check_ok=false")
        return _err("CONFLICT", "约束冲突：status=expired/banned 时 last_check_ok 必须为 false")

    # No success without effect
    if not changed:
        _log(endpoint, 409, cookie_session_id, "CONFLICT", "no changes applied")
        return _err("CONFLICT", "未发生任何更新（参数与当前值相同）")

    new_sess["updated_at"] = now
    sessions[idx] = new_sess
    _save("cookie_sessions.json", sessions)

    _log(endpoint, 200, cookie_session_id, None, None)
    return {"cookie_session": new_sess}

def list_notes(status=None, author_platform_id=None, keyword=None, page_size=None, page_token=None, order_by=None, **_extra):
    import json, os, datetime, re, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0444000" if __import__("os").path.isdir("./environment_mix/0444000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    endpoint = "list_notes"

    def _log(status_code, error_code=None, message=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": endpoint,
            "cookie_session_id": None,
            "status": status_code,
            "error_code": error_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        }
        if extra is not None:
            row["extra"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    allowed_status = ["discovered", "fetched", "stale", "blocked"]
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log(400, "VALIDATION_ERROR", "status invalid")
            return _err("VALIDATION_ERROR", "status 非法", field="status", allowed=allowed_status)

    if author_platform_id is not None and not isinstance(author_platform_id, str):
        _log(400, "VALIDATION_ERROR", "author_platform_id must be string")
        return _err("VALIDATION_ERROR", "author_platform_id 必须为字符串", field="author_platform_id")

    if keyword is not None:
        if not isinstance(keyword, str):
            _log(400, "VALIDATION_ERROR", "keyword must be string")
            return _err("VALIDATION_ERROR", "keyword 必须为字符串", field="keyword")
        if keyword.strip() == "":
            _log(400, "VALIDATION_ERROR", "keyword empty")
            return _err("VALIDATION_ERROR", "keyword 不能为空字符串", field="keyword")

    if page_size is None:
        page_size = 20
    if not isinstance(page_size, int) or isinstance(page_size, bool):
        _log(400, "VALIDATION_ERROR", "page_size must be integer")
        return _err("VALIDATION_ERROR", "page_size 必须为整数", field="page_size")
    if page_size < 1 or page_size > 100:
        _log(400, "VALIDATION_ERROR", "page_size out of range")
        return _err("VALIDATION_ERROR", "page_size 必须在 1-100 之间", field="page_size")

    allowed_order = ["updated_at_desc", "updated_at_asc", "created_at_desc", "created_at_asc", "last_content_fetched_at_desc"]
    if order_by is None:
        order_by = "updated_at_desc"
    if not isinstance(order_by, str) or order_by not in allowed_order:
        _log(400, "VALIDATION_ERROR", "order_by invalid")
        return _err("VALIDATION_ERROR", "order_by 非法", field="order_by", allowed=allowed_order)

    offset = 0
    if page_token is not None:
        if not isinstance(page_token, str) or page_token.strip() == "":
            _log(400, "VALIDATION_ERROR", "page_token invalid")
            return _err("VALIDATION_ERROR", "page_token 非法", field="page_token")
        # accept either plain integer or base64("o:<int>")
        pt = page_token.strip()
        if re.fullmatch(r"\d+", pt):
            offset = int(pt)
        else:
            try:
                raw = base64.urlsafe_b64decode(pt.encode("utf-8") + b"=" * (-len(pt) % 4)).decode("utf-8")
                if not raw.startswith("o:") or not raw[2:].isdigit():
                    _log(400, "VALIDATION_ERROR", "page_token decode invalid")
                    return _err("VALIDATION_ERROR", "page_token 非法", field="page_token")
                offset = int(raw[2:])
            except Exception:
                _log(400, "VALIDATION_ERROR", "page_token decode failed")
                return _err("VALIDATION_ERROR", "page_token 非法", field="page_token")
        if offset < 0:
            _log(400, "VALIDATION_ERROR", "page_token offset negative")
            return _err("VALIDATION_ERROR", "page_token 非法", field="page_token")

    notes = _load("notes.json")
    if not isinstance(notes, list):
        notes = []

    def _contains(hay, needle):
        if hay is None:
            return False
        if not isinstance(hay, str):
            return False
        return needle.lower() in hay.lower()

    filtered = []
    kw = keyword.strip().lower() if isinstance(keyword, str) else None
    for n in notes:
        if not isinstance(n, dict):
            continue
        if status is not None and n.get("status") != status:
            continue
        if author_platform_id is not None and n.get("author_platform_id") != author_platform_id:
            continue
        if kw is not None:
            if not (_contains(n.get("title"), kw) or _contains(n.get("content_text"), kw)):
                continue
        filtered.append(n)

    def _key_dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    if order_by == "updated_at_desc":
        filtered.sort(key=lambda r: (_key_dt(r.get("updated_at")) is None, _key_dt(r.get("updated_at"))), reverse=True)
    elif order_by == "updated_at_asc":
        filtered.sort(key=lambda r: (_key_dt(r.get("updated_at")) is None, _key_dt(r.get("updated_at"))))
    elif order_by == "created_at_desc":
        filtered.sort(key=lambda r: (_key_dt(r.get("created_at")) is None, _key_dt(r.get("created_at"))), reverse=True)
    elif order_by == "created_at_asc":
        filtered.sort(key=lambda r: (_key_dt(r.get("created_at")) is None, _key_dt(r.get("created_at"))))
    elif order_by == "last_content_fetched_at_desc":
        filtered.sort(key=lambda r: (_key_dt(r.get("last_content_fetched_at")) is None, _key_dt(r.get("last_content_fetched_at"))), reverse=True)

    total = len(filtered)
    page = filtered[offset: offset + page_size]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"o:{next_offset}".encode("utf-8")).decode("utf-8").rstrip("=")

    _log(200, None, None, extra={"total": total, "returned": len(page), "offset": offset, "order_by": order_by})
    return {
        "notes": page,
        "pagination": {
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "page_size": page_size
        }
    }

def get_note(note_id, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0444000" if __import__("os").path.isdir("./environment_mix/0444000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_note"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error_code=None, message=None, extra=None, cookie_session_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        rid = f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}"
        logs.append({
            "id": rid,
            "endpoint": endpoint,
            "cookie_session_id": cookie_session_id,
            "status": status,
            "error_code": error_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "extra": extra or {}
        })
        _save("request_logs.json", logs)

    try:
        if not isinstance(note_id, str) or not note_id.strip():
            _log("error", "VALIDATION_ERROR", "note_id invalid", extra={"field": "note_id"})
            return _err("VALIDATION_ERROR", "note_id 不能为空且必须为 string", field="note_id")
        note_id = note_id.strip()

        # Tool schema says notes.id format. Real usage observed also passes platform note_id; accept both.
        is_internal = bool(re.match(r"^xhs_note_[A-Za-z0-9]+$", note_id))
        is_platformish = bool(re.match(r"^[0-9a-fA-F]{16,64}$", note_id))
        if not (is_internal or is_platformish):
            _log("error", "VALIDATION_ERROR", "note_id format invalid", extra={"field": "note_id", "note_id": note_id})
            return _err("VALIDATION_ERROR", "note_id 必须为 notes.id（xhs_note_...）或平台 note_id（16-64位十六进制）", field="note_id", note_id=note_id)

        notes = _load("notes.json")
        if not isinstance(notes, list):
            notes = []

        found = None
        if is_internal:
            for n in notes:
                if isinstance(n, dict) and n.get("id") == note_id:
                    found = n
                    break
        else:
            for n in notes:
                if isinstance(n, dict) and n.get("platform_note_id") == note_id:
                    found = n
                    break

        if found is None:
            _log("error", "NOT_FOUND", "note not found", extra={"note_id": note_id})
            return _err("NOT_FOUND", "note 不存在", note_id=note_id)

        _log("success", None, None, extra={"note_id": note_id})
        return {"note": found}
    except Exception as e:
        _log("error", "UPSTREAM_PARSE_ERROR", "internal error", extra={"detail": str(e)})
        return _err("UPSTREAM_PARSE_ERROR", "服务内部错误", detail=str(e))
